package com.bank.mem;

import java.util.logging.Logger;

// Total container memory = heap + off-heap(stacks/metaspace/codecache) + direct buffers.
// The cgroup limit caps the TOTAL, not just the heap.
public class ContainerMemoryModel {
    private static final Logger log = Logger.getLogger(ContainerMemoryModel.class.getName());
    private final int limitMiB;
    private int heapMiB, metaspaceMiB, threadStacksMiB, directBuffersMiB;

    public ContainerMemoryModel(int limitMiB) { this.limitMiB = limitMiB; }

    public void setHeap(int m) { heapMiB = m; }
    public void setMetaspace(int m) { metaspaceMiB = m; }
    public void setThreadStacks(int m) { threadStacksMiB = m; }
    public void setDirectBuffers(int m) { directBuffersMiB = m; }

    public int total() { return heapMiB + metaspaceMiB + threadStacksMiB + directBuffersMiB; }
    public int limit() { return limitMiB; }

    public void report() {
        log.info(() -> "mem: heap=" + heapMiB + " meta=" + metaspaceMiB
                + " stacks=" + threadStacksMiB + " direct=" + directBuffersMiB
                + " TOTAL=" + total() + "MiB / limit=" + limitMiB + "MiB"
                + " (dashboard shows only heap=" + heapMiB + ")");
    }
}
