package com.bank.mem;

import java.util.logging.Logger;

// Computes a container-aware max heap: limit * MaxRAMPercentage/100.
public class JvmSizer {
    private static final Logger log = Logger.getLogger(JvmSizer.class.getName());

    public int maxHeapMiB(int containerLimitMiB, double maxRamPercent) {
        int heap = (int) Math.floor(containerLimitMiB * maxRamPercent / 100.0);
        log.info(() -> "JVM container-aware: -XX:MaxRAMPercentage=" + maxRamPercent
                + " on limit " + containerLimitMiB + "MiB -> maxHeap=" + heap + "MiB");
        return heap;
    }
}
