package com.bank.mem;

import java.util.logging.Logger;

// Fires when total resident memory crosses the cgroup limit (SIGKILL, exit 137).
public class OomKiller {
    private static final Logger log = Logger.getLogger(OomKiller.class.getName());

    public boolean check(ContainerMemoryModel m) {
        if (m.total() > m.limit()) {
            log.severe(() -> "OOMKilled: total " + m.total() + "MiB > limit " + m.limit()
                    + "MiB — SIGKILL, exit code 137 (heap looked fine!)");
            return true;
        }
        log.info("memory within limit — container stays up");
        return false;
    }
}
