package com.bank.mem;

import java.math.BigDecimal;
import java.util.logging.*;

public class MemorySizingDemo {
    private static final Logger log = Logger.getLogger(MemorySizingDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        OomKiller oom = new OomKiller();

        // BAD: limit 1024MiB but heap set to 960, plus off-heap -> OOMKilled
        ContainerMemoryModel bad = new ContainerMemoryModel(1024);
        bad.setHeap(960); bad.setMetaspace(96); bad.setThreadStacks(80); bad.setDirectBuffers(120);
        bad.report();
        boolean killed = oom.check(bad);  // total 1256 > 1024 -> killed
        log.info("transfer attempt under BAD sizing killed=" + killed);

        // GOOD: container-aware heap = 75% of limit, room for off-heap
        JvmSizer sizer = new JvmSizer();
        int heap = sizer.maxHeapMiB(1024, 75);  // 768
        ContainerMemoryModel good = new ContainerMemoryModel(1024);
        good.setHeap(heap); good.setMetaspace(96); good.setThreadStacks(80); good.setDirectBuffers(60);
        good.report();
        if (!oom.check(good)) {
            rajesh.debit(new BigDecimal("50000")); priya.credit(new BigDecimal("50000"));
            log.info("transfer SAV2001->CUR3001 Rs.50000 SUCCESS under right-sized memory");
        }
    }
}
